var PUA = {};
// ---- END kakijun-data ----

// 筆の幅（字の 0〜100 の座標。data/kana/proto.html と同じ）：
//   太い筆は 13。データの画の w（画の長さを 3 つに分けた所ごとの、測ったインクの幅）があれば、ガードは w + 1.75、細い筆は w + 1.25 を
//   その 3 分の 1 ごとに（同じ path を 3 回、それぞれの区間だけ破線で描く）。w がなければガード 12、細い筆 9 の 1 本
var BRUSH = {wide: 13, guard: 12, narrow: 9, guardExtra: 1.75, narrowExtra: 1.25};
// 区間 [a, b] と幅の列
function segsOf(w, extra, fixed){
  if (!Array.isArray(w) || !w.length || !w.every(function(x){ return typeof x === "number" && isFinite(x); })) return [[0, 1, fixed]];
  return w.map(function(x, j){ return [j / w.length, (j + 1) / w.length, x + extra]; });
}
var FAMILY = "Egatari Kana";
var END_JA = {tome: "とめ", hane: "はね", harai: "はらい"};
var ON = function(v){ return /^(on|true|yes)$/i.test(String(v || "").trim()); };
// 中心線の path（M L Q C、絶対座標。tools/test-kakijun.mjs が、データにほかの命令がないことを確かめる）を点の列にする
function sample(d){
  var tk = String(d).match(/[MLQC]|-?\d*\.?\d+(?:e[-+]?\d+)?/gi) || [], i = 0, cmd = "", x = 0, y = 0, pts = [];
  var num = function(){ return +tk[i++]; };
  while (i < tk.length){
    if (/^[A-Za-z]$/.test(tk[i])) cmd = tk[i++].toUpperCase();
    if (cmd === "M"){ x = num(); y = num(); pts.push([x, y]); cmd = "L"; }
    else if (cmd === "L"){ x = num(); y = num(); pts.push([x, y]); }
    else if (cmd === "Q"){
      var qx = num(), qy = num(), ex = num(), ey = num();
      for (var a = 1; a <= 12; a++){ var u = a / 12, v = 1 - u; pts.push([v * v * x + 2 * v * u * qx + u * u * ex, v * v * y + 2 * v * u * qy + u * u * ey]); }
      x = ex; y = ey;
    } else if (cmd === "C"){
      var c1x = num(), c1y = num(), c2x = num(), c2y = num(), cx = num(), cy = num();
      for (var b = 1; b <= 20; b++){ var s = b / 20, r = 1 - s; pts.push([r * r * r * x + 3 * r * r * s * c1x + 3 * r * s * s * c2x + s * s * s * cx, r * r * r * y + 3 * r * r * s * c1y + 3 * r * s * s * c2y + s * s * s * cy]); }
      x = cx; y = cy;
    } else throw new Error("m-kakijun: unsupported path command in " + d);
  }
  var cum = [0];
  for (var j = 1; j < pts.length; j++) cum.push(cum[j - 1] + Math.hypot(pts[j][0] - pts[j - 1][0], pts[j][1] - pts[j - 1][1]));
  return {pts: pts, cum: cum, L: cum[cum.length - 1]};
}
// 長さで f（0〜1）の所の点と、そこでの向き（単位ベクトル）
function at(sp, f){
  var L = sp.L * Math.max(0, Math.min(1, f)), c = sp.cum, p = sp.pts, j = 1;
  while (j < p.length - 1 && c[j] < L) j++;
  var seg = c[j] - c[j - 1] || 1, u = Math.max(0, Math.min(1, (L - c[j - 1]) / seg));
  var dx = p[j][0] - p[j - 1][0], dy = p[j][1] - p[j - 1][1], n = Math.hypot(dx, dy) || 1;
  return {x: p[j - 1][0] + dx * u, y: p[j - 1][1] + dy * u, dx: dx / n, dy: dy / n};
}
// 向き：始めの数単位（終わりの数単位）を通して見た向き
function dirAt(sp, from, len){
  var a = at(sp, from), b = at(sp, from + (len / (sp.L || 1)) * (from > 0.5 ? -1 : 1)), dx = from > 0.5 ? a.x - b.x : b.x - a.x, dy = from > 0.5 ? a.y - b.y : b.y - a.y, n = Math.hypot(dx, dy) || 1;
  return {x: a.x, y: a.y, dx: dx / n, dy: dy / n};
}
var UID = 0, FACE = null;
// path の [lo, hi] の部分だけ（pathLength = 1）。長さ 0 の破線でも丸い端が描かれるので隠す
function part(p, lo, hi){ var len = hi - lo; p.setAttribute("stroke-dasharray", Math.max(len, 0).toFixed(4) + " 2"); p.setAttribute("stroke-dashoffset", (-lo).toFixed(4)); p.style.visibility = len > 1e-6 ? "visible" : "hidden"; }
// ---- 字のインクの層と、1 画の描き方。描き方を変えるときはこの 2 つだけを入れ替える ----
// buildInk(D, g, c, tf, text)：字 c のインクの層を g の中に作る（tf は字の座標への変換、text(親, 塗り, 字) は字の SVG text を作る）
// drawStroke(c, j, f)：字 c の j 画目を、書いた割合 f（0〜1）の状態にする（純粋：前の状態に頼らない）
// 2 つの描き方：
